import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import fm from 'front-matter';
import markdownToHtml from '../utils/mdToHtml';

interface Frontmatter {  
  title: string;
  subtitle: string;
  date: string;
  keywords: string[];
}

interface PostData extends Frontmatter {
  content: string;
}

const PostPage: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const [post, setPost] = useState<PostData | null>(null);



  useEffect(() => {
    const fetchPost = async () => {
      const file = await import(`../posts/${slug}.md`);
      const parsed = fm<{ title: string; subtitle: string; date: string; keywords: string[] }>(file.default);
      const htmlContent = await markdownToHtml(parsed.body);
      const postData: PostData = { 
        title: parsed.attributes.title, 
        subtitle: parsed.attributes.subtitle, 
        date: parsed.attributes.date, 
        keywords: parsed.attributes.keywords, 
        content: htmlContent 
      };
      setPost(postData);
    };

    fetchPost();
  }, [slug]);

  if (!post) return <div>Loading...</div>;

  return (
    <div className="prose prose-lg mx-auto mt-10">
      <h1 className="text-4xl font-bold mb-2">{post.title}</h1>
      <h2 className="text-2xl text-gray-700 mb-4">{post.subtitle}</h2>
      <p className="text-gray-500 mb-4">{new Date(post.date).toDateString()}</p>
      <div className="flex flex-wrap mb-4">
        {post.keywords.map((keyword, index) => (
          <span 
            key={index} 
            className="bg-gray-200 text-gray-700 px-2 py-1 rounded-full text-sm mr-2 mb-2"
          >
            {keyword}
          </span>
        ))}
      </div>
      <div dangerouslySetInnerHTML={{ __html: post.content }} />
    </div>
  );
};

export default PostPage;
